const m = (typeof process !== "undefined" && process.memoryUsage) ? process.memoryUsage() : null;

const debugObj = {
  payload: {
    type: typeof p,
    isArray: isArr,
    count: isArr ? p.length : null,
    sample: isArr ? p[0] : p,                         // 1º item (confere os campos)
    fields: isArr && p[0] ? Object.keys(p[0]) : null, // nomes reais (id? val?)
    semId: isArr ? p.filter((it) => it == null || it.id == null).length : null, // causa do 'key undefined'
    idTypes: isArr ? p.reduce((a, it) => {
      const t = it == null ? "null" : typeof it.id;
      a[t] = (a[t] || 0) + 1; return a;               // se aparecer 'number', coage com $string(id)
    }, {}) : null,
    groupKeys: isArr ? Object.keys(p.reduce((g, it) => {
      if (it && it.id != null) g[String(it.id)] = 1; return g;
    }, {})) : null,                                    // como ficariam as chaves do agrupamento
  },
  nodeRed: m
    ? { rss_mb: mb(m.rss), heapUsed_mb: mb(m.heapUsed), heapTotal_mb: mb(m.heapTotal), pid: process.pid, uptime_s: Math.round(process.uptime()) }
    : "process indisponível no sandbox",
};

node.warn(debugObj);   // <- um único warn
return msg;            // segue o fluxo

// Reabilita o sync respeitando holds ativos.
// A garantia real anti-corrida fica no Postgres (intent ENABLE);
// aqui e' so' gating local p/ nao martelar o banco a cada tick.
const status = global.get('mqttSyncStatus');
const hold   = global.get('mqttSyncHold');
const agora  = Date.now();

if (status === 'enable') return null;            // ja' ok

if (hold && hold.expiresAtMs && agora < hold.expiresAtMs) {
    const restam = Math.round((hold.expiresAtMs - agora) / 1000);
    node.warn(`WATCHDOG: hold ${hold.reasonCode || ''} ativo, faltam ${restam}s -- mantem disable`);
    return null;                                  // respeita o hold
}

// disable sem hold (ou expirado) -> monta envelope ENABLE v2.0
const now = new Date();
const bucket = Math.floor(now.getTime() / (5 * 60 * 1000));
const uuid = (typeof crypto !== 'undefined' && crypto.randomUUID)
    ? crypto.randomUUID()
    : `${now.getTime()}-${Math.random().toString(16).slice(2)}`;

msg.payload = {
    schemaVersion: "2.0",
    intent: "ENABLE",                 // ENABLE respeita hold; FORCE_ENABLE seria override
    hold: null,
    scope: { level: "CENTRAL", targets: [] },
    actor: {
        system: "WATCHDOG",
        instanceId: env.get("INSTANCE_ID") || "nodered-ilha-al1",
        version: env.get("APP_VERSION") || "3.0.0",
        user: { userId: "system", userName: "watchdog", role: "system" },
        onBehalfOf: null,
        requestIp: null
    },
    request: {
        requestId: uuid,
        correlationId: `watchdog-${bucket}`,
        idempotencyKey: `watchdog:enable:${bucket}`,
        requestedAt: now.toISOString(),
        requestedAtMs: now.getTime()
    }
};

msg._internal = true;   // marca origem interna (nao-HTTP)
return msg;

// Valida o envelope v2.0 e prepara o $1::jsonb para set_mqtt_sync_status().
// Roteado pelo Switch a jusante via msg.payload.status: valid | invalid
const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const intent = String(body.intent || '').toUpperCase();

let status = String(body.mqttSyncStatus || body.status || '').toLowerCase();
if (!status) {
    status = ({
        DISABLE: 'disable', FORCE_DISABLE: 'disable',
        ENABLE:  'enable',  FORCE_ENABLE:  'enable',
    })[intent] || '';
}

const isValid = (intent === 'QUERY') || status === 'enable' || status === 'disable';
if (!isValid) {
    msg.statusCode = 400;
    msg.payload = {
        status: 'invalid', ok: false,
        error: 'payload invalido: informe intent (DISABLE|ENABLE|FORCE_*|QUERY) ou mqttSyncStatus (enable|disable)',
        intent: intent || null,
    };
    return msg;
}

// cache OTIMISTA -> sera reconciliado com o Postgres no tail
if (status) {
    global.set('mqttSyncStatus', status);
    if (status === 'disable' && body.hold && body.hold.ttlSeconds) {
        const reqMs = (body.request && body.request.requestedAtMs) || Date.now();
        global.set('mqttSyncHold', {
            holdId: body.hold.holdId || null,
            reasonCode: body.hold.reasonCode || null,
            expiresAtMs: reqMs + body.hold.ttlSeconds * 1000
        });
    } else if (status === 'enable') {
        global.set('mqttSyncHold', null);
    }
}

msg.params = [JSON.stringify(body)];   // $1::jsonb
msg.payload = { status: 'valid', mqttSyncStatus: status || null, intent: intent || null };
return msg;

// Tail do WATCHDOG: reconcilia o cache com o resultado real do Postgres
// e monta um payload de LOG para o debug (NAO ha' resposta HTTP).
let row = null;
if (msg.payload && msg.payload[0] && msg.payload[0].result) {
    row = msg.payload[0].result;
} else if (msg.payload && msg.payload.rows && msg.payload.rows[0]) {
    row = msg.payload.rows[0].result;
}

if (!row) {
    node.warn('WATCHDOG: Postgres nao retornou result');
    msg.payload = { ok: false, error: 'no result' };
    return msg;
}

// reconcilia o cache com o que foi REALMENTE persistido
if (row.ok && row.mqttSyncStatus) {
    global.set('mqttSyncStatus', row.mqttSyncStatus);
    if (row.mqttSyncStatus === 'enable') global.set('mqttSyncHold', null);
}

const aplicou = row.mqttSyncStatus === 'enable';
node.warn(aplicou
    ? `WATCHDOG: reabilitado por ${row.lastUpdateBy} em ${row.lastUpdateChange}`
    : `WATCHDOG: enable nao aplicado (status=${row.mqttSyncStatus}, provavel hold) -- ultima mudanca: ${row.lastUpdateBy} @ ${row.lastUpdateChange}`);

// payload de LOG p/ o debug (onde estaria a response)
msg.payload = {
    source: 'WATCHDOG',
    applied: aplicou,
    mqttSyncStatus: row.mqttSyncStatus,
    lastUpdateChange: row.lastUpdateChange || null,
    lastUpdateBy: row.lastUpdateBy || null
};
return msg;

const mqttSyncStatys = global.get('mqttSyncStatus');

//node.warn('VERIFICANDO mqttSyncStatys: ' + mqttSyncStatys);

// mantém o que já existe no payload e só acrescenta o atributo
if (msg.payload === null || typeof msg.payload !== 'object' || Array.isArray(msg.payload)) {
  msg.payload = {};
}

msg.payload.mqttSyncStatys = mqttSyncStatys;

